props.css:
.hero{position:relative;min-height:660px;display:flex;flex-direction:column;justify-content:center;overflow:hidden;background:linear-gradient(180deg,#0B1F3A 0%,#123163 48%,#071A33 100%);color:#fff;box-sizing:border-box;padding:72px 32px 64px}
.hero-grid{position:absolute;inset:0;opacity:.3;background-image:linear-gradient(rgba(125,211,252,.16) 1px,transparent 1px),linear-gradient(90deg,rgba(125,211,252,.16) 1px,transparent 1px);background-size:60px 60px;-webkit-mask-image:linear-gradient(to bottom,#000,transparent 88%);mask-image:linear-gradient(to bottom,#000,transparent 88%)}
.orb{position:absolute;border-radius:50%;filter:blur(90px);pointer-events:none}
.orb-a{width:460px;height:460px;right:-100px;top:-140px;background:rgba(56,189,248,.32)}
.orb-b{width:420px;height:420px;left:-140px;bottom:-180px;background:rgba(59,130,246,.26)}
.hero-inner{position:relative;z-index:2;max-width:1060px;width:100%;margin:0 auto;text-align:center}
.eyebrow{display:inline-flex;align-items:center;gap:10px;padding:9px 20px;border:1px solid rgba(147,197,253,.28);border-radius:999px;background:rgba(255,255,255,.06);font-size:11px;letter-spacing:2px;color:#bfdbfe;-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}
.dot{width:7px;height:7px;border-radius:50%;background:#38bdf8;box-shadow:0 0 12px #38bdf8}
.hero-title{margin:28px 0 20px;font-size:clamp(42px,6.2vw,78px);line-height:1.12;font-weight:800;letter-spacing:-1.5px;color:#fff}
.hero-title em{font-style:normal;background:linear-gradient(90deg,#7dd3fc,#60a5fa 48%,#a78bfa);-webkit-background-clip:text;background-clip:text;color:transparent}
.hero-lead{max-width:700px;margin:0 auto;font-size:17px;line-height:1.95;color:#c7ddf7}
.hero-actions{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin-top:36px}
.btn{display:inline-flex;align-items:center;gap:10px;padding:15px 30px;border-radius:10px;font-size:15px;font-weight:600;text-decoration:none;transition:transform .2s,box-shadow .2s,background .2s}
.btn:hover{transform:translateY(-3px)}
.btn-main{background:linear-gradient(135deg,#38bdf8,#2563eb);color:#fff;box-shadow:0 12px 32px rgba(56,189,248,.32)}
.btn-sub{border:1px solid rgba(191,219,254,.42);color:#e0f2fe;background:rgba(255,255,255,.06)}
.hero-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;max-width:780px;margin:58px auto 0;padding-top:34px;border-top:1px solid rgba(147,197,253,.2)}
.metric b{display:block;font-size:36px;font-weight:800;color:#fff;line-height:1}
.metric b sup{font-size:15px;font-weight:600;margin-left:2px;color:#7dd3fc}
.metric span{display:block;margin-top:9px;font-size:12px;letter-spacing:1px;color:#93c5fd}
.hero-scroll{position:absolute;left:50%;bottom:18px;transform:translateX(-50%);z-index:2;display:flex;align-items:center;gap:10px;font-size:10px;letter-spacing:3px;color:rgba(191,219,254,.55)}
.hero-scroll span{display:block;width:1px;height:24px;background:linear-gradient(#7dd3fc,transparent)}
@media(max-width:768px){.hero{min-height:580px;padding:56px 20px}.hero-metrics{grid-template-columns:repeat(2,1fr);gap:26px;margin-top:42px}.hero-lead{font-size:15px}.btn{padding:13px 22px}.hero-scroll{display:none}}

.cap-wrap{background:linear-gradient(180deg,#ffffff 0%,#f8fafc 100%);padding:88px 32px;box-sizing:border-box}
.cap-head{text-align:center;margin-bottom:52px}
.cap-kicker{font-size:12px;letter-spacing:5px;color:#0284c7;font-weight:800}
.cap-head h2{margin:14px 0 10px;font-size:clamp(30px,4vw,46px);font-weight:800;color:#0f172a;letter-spacing:-.5px}
.cap-head p{margin:0;color:#64748b;font-size:15px}
.cap-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;max-width:1160px;margin:0 auto}
.cap{position:relative;background:#fff;border:1px solid #e8edf5;border-radius:18px;padding:34px 28px 30px;overflow:hidden;transition:transform .25s,box-shadow .25s,border-color .25s}
.cap:before{content:"";position:absolute;left:0;top:0;width:100%;height:3px;background:linear-gradient(90deg,#38bdf8,#2563eb);opacity:0;transition:opacity .25s}
.cap:hover{transform:translateY(-7px);box-shadow:0 24px 50px rgba(11,31,58,.13);border-color:#bfdbfe}
.cap:hover:before{opacity:1}
.cap-ico{width:52px;height:52px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:24px;color:#0284c7;background:linear-gradient(135deg,#eff6ff,#dbeafe);margin-bottom:22px}
.cap h3{margin:0 0 11px;font-size:19px;color:#0f172a;font-weight:700}
.cap p{margin:0;font-size:14px;line-height:1.85;color:#64748b}
@media(max-width:900px){.cap-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:600px){.cap-grid{grid-template-columns:1fr}.cap-wrap{padding:60px 20px}}

.proc-wrap{background:#fff;padding:88px 32px;box-sizing:border-box}
.proc-head{text-align:center;margin-bottom:56px}
.proc-kicker{font-size:12px;letter-spacing:5px;color:#0284c7;font-weight:800}
.proc-head h2{margin:14px 0 10px;font-size:clamp(30px,4vw,46px);font-weight:800;color:#0f172a}
.proc-head p{margin:0;color:#64748b;font-size:15px}
.proc-grid{position:relative;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px;max-width:1140px;margin:0 auto}
.proc-grid:before{content:"";position:absolute;left:8%;right:8%;top:31px;height:2px;background:linear-gradient(90deg,#bae6fd,#93c5fd);z-index:0}
.step{position:relative;z-index:1;text-align:center;padding:0 12px}
.step-num{width:62px;height:62px;margin:0 auto 22px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:800;color:#fff;background:linear-gradient(135deg,#38bdf8,#2563eb);box-shadow:0 0 0 8px #fff,0 10px 24px rgba(37,99,235,.26)}
.step h3{margin:0 0 10px;font-size:18px;color:#0f172a;font-weight:700}
.step p{margin:0;font-size:14px;line-height:1.8;color:#64748b}
@media(max-width:800px){.proc-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:40px 20px}.proc-grid:before{display:none}.proc-wrap{padding:60px 20px}}
@media(max-width:480px){.proc-grid{grid-template-columns:1fr}}

.mc-header{background:#fff}
.mc-header-in{max-width:1200px;margin:0 auto;padding:26px 14px;display:flex;align-items:center;gap:24px}
.mc-brand{display:flex;align-items:center;gap:8px;flex-shrink:0}
.mc-logo-txt{display:flex;flex-direction:column;line-height:1}
.mc-logo-txt b{font-size:26px;font-weight:800;color:#1b1b1b;letter-spacing:1px}
.mc-logo-txt span{font-size:11px;font-weight:700;letter-spacing:3px;color:#1b1b1b;margin-top:6px}
.mc-logo-gear{width:41px;height:43px}
.mc-slogan{display:flex;flex-direction:column;gap:6px;color:#999;font-size:13px;padding-left:24px;border-left:1px solid #eee}
.mc-slogan b{font-size:20px;color:#FE5900;font-weight:700;letter-spacing:1px}
.mc-search{margin-left:auto;display:flex;height:32px;align-items:stretch}
.mc-search-sel{display:flex;align-items:center;gap:8px;padding:0 12px;border:1px solid #ddd;border-right:none;background:#fafafa;color:#666;font-size:12px}
.mc-search-sel span{color:#999}
.mc-search input{width:150px;border:1px solid #ddd;padding:0 10px;font-size:12px;outline:none;color:#666}
.mc-search button{border:none;background:#FE5900;color:#fff;font-size:13px;padding:0 18px;cursor:pointer}
.mc-nav-toggle{position:absolute;opacity:0;pointer-events:none;width:1px;height:1px}
.mc-hd-menu-btn{display:none;align-items:center;justify-content:center;width:40px;height:36px;border:1px solid #ddd;border-radius:4px;color:#FE5900;font-size:18px;cursor:pointer;user-select:none;margin-left:auto}
.mc-hd-menu-btn span{transition:transform .2s}
.mc-nav-toggle:checked ~ .mc-header-in .mc-hd-menu-btn span{transform:rotate(90deg)}
.mc-hd-mobile-nav{display:none;flex-direction:column;background:#fff;border-top:1px solid #eee;padding:6px 14px 12px}
.mc-nav-toggle:checked ~ .mc-hd-mobile-nav{display:flex}
.mc-hd-mobile-nav a{display:block;padding:12px 6px;text-decoration:none;color:#1b1b1b;font-size:14px;border-bottom:1px solid #f5f5f5}
@media(max-width:900px){.mc-header-in{flex-wrap:wrap;gap:16px}.mc-search{margin-left:0;width:100%}.mc-search input{flex:1}.mc-slogan{padding-left:0;border:none}}
@media(max-width:640px){.mc-header-in{padding:14px 12px}.mc-logo-txt b{font-size:20px}.mc-slogan b{font-size:16px}.mc-slogan span{display:none}.mc-hd-menu-btn{display:flex;order:2}.mc-search{order:3}}

.mc-nav{background:#fff;border-top:1px solid #eee}
.mc-nav-in{max-width:1200px;margin:0 auto;padding:0 14px;display:grid;grid-template-columns:78px repeat(6,1fr)}
.mc-nav a{display:flex;align-items:center;justify-content:center;height:70px;text-decoration:none;color:#1b1b1b;font-size:15px;border-right:1px solid #f0f0f0;box-sizing:border-box}
.mc-nav-home{font-size:22px;color:#FE5900!important}
.mc-nav-item.active{color:#FE5900!important;border-bottom:3px solid #FE5900;font-weight:600}
.mc-nav a:hover{background:#fff8f4}
@media(max-width:640px){.mc-nav{display:none}}

.mc-col-title{margin:0 0 18px;padding-bottom:10px;border-bottom:2px solid #FE5900;display:flex;align-items:baseline;gap:8px}
.mc-col-title b{font-size:19px;color:#1b1b1b}
.mc-col-title span{font-size:10px;color:#aaa;letter-spacing:1px}
.mc-contact{list-style:none;margin:0;padding:0}
.mc-contact li{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px dashed #e5e5e5}
.mc-contact img{width:34px;height:34px}
.mc-contact div{display:flex;flex-direction:column;gap:4px}
.mc-contact span{font-size:12px;color:#999}
.mc-contact b{font-size:14px;color:#1b1b1b}
